window.OLAYLAR_EK18 = [{"t":"1455-06-20","b":"Prizren'in fethi — Kosova'da Osmanlı sancak merkezi","tur":"fetih","onem":3,"dunya":2,"kapsam":"ic","etiket":["toprak-kazanc","savas","konu-askeri"],"yer":"Prizren","yer_id":"Prizren","kisiler":"Fâtih Sultan Mehmed, Curac Brankoviç (Vılkoğlu)","d":"4 Receb 859'da (20 Haziran 1455) Fâtih Sultan Mehmed kumandasındaki Osmanlı ordusu, Sırp despotu Curac Brankoviç — Osmanlı kaynaklarında Vılkoğlu — ile yapılan savaştan sonra Prizren'i ele geçirdi. Şehir XIII. yüzyıl ortalarında Bizans'tan Sırp Krallığı'na geçmiş, Kral Milutin, Çar Duşan ve Kral Uroş dönemlerinde kraliyet ikametgâhı olmuştu; Duşan'ın ölümünden sonra önemi azalmıştı. Fetihten sonra bir sancağın merkezi yapıldı ve 1912'ye kadar dört buçuk asır bu sıfatını korudu. Prizren, Yugoslavya'nın parçalanmasından önce Balkanlar'ın üç dilinin — Arnavutça, Türkçe ve Sırpça — birlikte konuşulduğu tek şehirdi.","kaynak":"prizren"}];

