// data/olaylar_ek20.js — paketle.py İNCELTTİ: ic_not* alanları yayına gitmez (kaynak dosya değişmedi)
window.OLAYLAR_EK20 = [{"bolge":2,"t":"1326-10-09","b":"Eşrefoğulları Beyliği'nin sonu — Beyşehir ve Seydişehir Hamîdoğulları'na geçti","tur":"fetih","onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kayip","beylik","konu-askeri"],"yer":"Beyşehir","yer_id":"Beyşehir","kisiler":"Demirtaş (Timurtaş) Noyan, Eşrefoğlu Süleyman Şah, Hamîdoğlu Dündar Bey","d":"İlhanlı Devleti'nin Anadolu genel valisi Emîr Çoban'ın oğlu Demirtaş, bağımsızlıklarını ilân eden Türkmen beyliklerine karşı harekete geçti ve Beyşehir'e girerek vaktiyle kendisini şikâyet eden Eşrefoğlu Süleyman Şah'ı öldürttü (9 Ekim 1326). Beyşehir ve Seydişehir yöresinde XIII. yüzyıl sonlarında kurulmuş olan Eşrefoğulları Beyliği böylece sona erdi. TDV'nin Hamîdoğulları maddesi devamını veriyor: Demirtaş'ın ortadan kaldırdığı Eşrefoğulları'na ait Beyşehir, Seydişehir, Akşehir ve Doğanhisar Hamîd beyliğinin sınırlarına katıldı. Aynı yıl Hamîdoğlu Dündar Bey de Demirtaş'a teslim edilerek öldürüldü. Bu topraklar 1381'de I. Murad'a 80.000 altın karşılığında satılarak Osmanlı idaresine geçecektir.","kaynak":"esrefogullari"},{"bolge":3,"t":"1344-10-28","b":"İzmir Limanı'nın Haçlı donanmasına kaybı — Aydınoğulları'nın deniz gücü kırıldı","tur":"savas","onem":4,"dunya":2,"kapsam":"dis","etiket":["toprak-kayip","savas","deniz","konu-askeri"],"yer":"İzmir","yer_id":"İzmir","kisiler":"Aydınoğlu Umur Bey, Papa VI. Clement","d":"Papa VI. Clement'in teşvikiyle Venedik, Cenova, Kıbrıs Krallığı, Rodos şövalyeleri ve Naksos düküne ait gemilerden kurulu Haçlı donanması, İzmir Limanı'nı Aydınoğulları'nın elinden aldı (28 Ekim 1344). Liman, Umur Bey'in babası Mehmed Bey tarafından Cenovalı Martino Zaccaria'dan 1328-1329'da alınmıştı ve Ege'de Aydınoğlu deniz gücünün üssüydü. 1334 Eylülünde aynı amaçla gelen bir Haçlı filosu geri çekilmek zorunda kalmıştı; bu ikinci sefer başarılı oldu. Umur Bey direnişi sürdürdü ve öteki Türk beylikleriyle birleşerek Haçlı donanmasını 17 Ocak 1345'te mağlûp ettiyse de liman geri alınamadı.","kaynak":"aydinogullari"},{"bolge":3,"t":"1366-01-01","b":"Karamanoğlu Alâeddin Bey Konya, Aksaray ve Niğde'yi Karaman topraklarına kattı","tur":"fetih","onem":2,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","beylik","konu-askeri"],"yer":"Konya","yer_id":"Konya","kisiler":"Karamanoğlu Alâeddin Bey","d":"Memlük Sultanlığı'nın Ermeni Krallığı'na son vererek bütün Çukurova'yı kendi topraklarına katmasından ve Orta Anadolu'daki Eretna Devleti'nde çıkan karışıklıklardan faydalanmak isteyen Karamanoğlu Alâeddin Bey, başta Konya (1366-1367) olmak üzere Niğde Karahisarı (Yeşilhisar), Aksaray, Akşehir, Ilgın, İshaklı ve Kayseri'yi Karamanlı topraklarına kattı. Konya, Selçuklu başşehri olarak taşıdığı ağırlık sebebiyle Karamanoğulları için yalnız bir şehir değil bir meşruiyet iddiasıydı.","kaynak":"karamanogullari"},{"bolge":4,"t":"1467-01-01","b":"Uzun Hasan Karakoyunlu Devleti'ne son verdi — Van gölü havzası Akkoyunlu'ya geçti","tur":"savas","onem":4,"dunya":2,"kapsam":"dis","etiket":["toprak-kazanc","savas","konu-askeri"],"yer":"Van","yer_id":"Eski Van (Tuşpa)","kisiler":"Uzun Hasan, Karakoyunlu Cihan Şah","d":"Akkoyunlu hükümdarı Uzun Hasan, 1467'de üzerine yürüyen amansız düşmanı Karakoyunlu hükümdarı Cihan Şah'ı gafil avlayarak Karakoyunlu Devleti'ne son verdi. 1438'den beri hüküm süren Cihan Şah'ın ortadan kalkmasıyla Van gölü havzası — Van, Bitlis, Bargiri (Muradiye), Hoşap ve Kotur — Karakoyunlu'dan Akkoyunlu idaresine geçti. Bu zafer Akkoyunlu Devleti'ni Doğu Anadolu ve İran'da tek büyük güç hâline getirdi ve Uzun Hasan'ı bir nesil sonra Osmanlı ile karşı karşıya getirecek yola soktu.","kaynak":"akkoyunlular"},{"bolge":3,"t":"1490-01-01","b":"Gürcistan Krallığı üçe bölündü — Kartli, Kaheti ve merkezi Kutaisi olan İmereti","tur":"siyasi","onem":4,"dunya":2,"kapsam":"dis","etiket":["devlet-bolunmesi","konu-siyasi"],"yer":"Kutaisi","yer_id":"Kutaisi","kisiler":"","d":"Bagratlı hânedanının yönettiği birleşik Gürcistan Krallığı, uzun bir iç mücadelenin ardından resmen üç krallığa ayrıldı: doğuda Tiflis merkezli Kartli, kuzeydoğuda Kaheti ve batıda merkezi Kutaisi olan İmereti. TDV'nin Gürcistan maddesi bölünmeyi teyit ediyor — 'Gürcistan üç krallığa (Kartliya, Kahetya, İmeretiya) ve beş beyliğe ayrıldı'. Bölünme, bir sonraki yüzyılın Osmanlı-Safevî çekişmesinde belirleyici oldu: 1555 Amasya Antlaşması'na göre İmeret, Dadyan, Güryel ve Daveli Osmanlı'ya; Kartli, Kahet ve Mosuk Safevî'ye bırakıldı. Yani atlasın batı ve doğu Gürcistan'ı ayrı efendilere bağlaması bu bölünmeden doğar. Yavuz Sultan Selim daha Trabzon valisi iken 1508'de İmeret (Açıkbaş) Krallığı'nı itaate ve haraca bağlamıştı.","kaynak":"gurcistan"},{"bolge":2,"t":"1315-04-28","b":"Memlük ordusu Malatya'ya girdi — şehir İlhanlı'dan Memlük idaresine geçti","tur":"fetih","onem":3,"dunya":2,"kapsam":"dis","etiket":["toprak-kazanc","savas","konu-askeri"],"yer":"Malatya","yer_id":"Eski Malatya (Battalgazi)","kisiler":"Seyfeddin Tengiz","d":"Memlükler, Dımaşk nâibi Seyfeddin Tengiz kumandasındaki bir orduyu Malatya üzerine sevketti; ordu 22 Muharrem 715'te (28 Nisan 1315) şehre girdi. Malatya o güne kadar İlhanlı hâkimiyetindeydi ve Fırat'ın batısında İlhanlı ile Memlük nüfuz alanlarının değdiği hattın kilit noktasıydı. Şehrin el değiştirmesi, iki devlet arasındaki uzun çekişmede Memlükler'in Yukarı Fırat'a doğru ilerleyişini gösterir. Malatya bu tarihten sonra bir süre Eretnaoğulları'nın idaresine girecek, 1338'den itibaren yeniden Memlük hâkimiyetine dönecektir.","kaynak":"malatya"},{"bolge":2,"t":"1338-01-01","b":"Malatya yeniden Memlük hâkimiyetine girdi — Eretnaoğulları idaresinin sonu","tur":"fetih","onem":3,"dunya":1,"kapsam":"dis","etiket":["toprak-kazanc","konu-askeri"],"yer":"Malatya","yer_id":"Eski Malatya (Battalgazi)","kisiler":"","d":"1315'te Memlük idaresine giren Malatya, İlhanlı Devleti'nin çözülme yıllarında bir süre Eretnaoğulları'nın eline geçmişti. TDV'nin Malatya maddesi dönüşü tek cümleyle veriyor: şehre 1338'den itibaren yeniden Memlükler hâkim oldu. Bu, Anadolu'nun güneydoğusunda İlhanlı sonrası boşluğun Memlük ve Eretna arasında paylaşıldığı yılların bir kesitidir.","kaynak":"malatya"},{"bolge":3,"t":"1510-07-25","b":"Trablusgarp'ın İspanyollar'ca işgali — Hafsî hâkimiyetinin sonu","tur":"savas","onem":4,"dunya":2,"kapsam":"dis","etiket":["toprak-kayip","savas","konu-askeri"],"yer":"Trablus","yer_id":"Trablus","kisiler":"Don Pedro Navarro","d":"Ammâroğulları'ndan sonra Trablusgarp'ta Hafsîler'in hâkimiyeti 1510 yılına kadar sürdü. O yıl şehir, Oliveto Kontu Don Pedro Navarro kumandasındaki İspanyollar tarafından işgal edildi; katliamdan kurtulan müslümanlar şehri terketti. İşgal, İspanya'nın Kuzey Afrika kıyısında Melilla'dan Trablus'a uzanan kale zincirinin doğu ucuydu. Trablusgarp halkı 925'te (1519) İstanbul'a bir heyet yollayarak İspanyol istilâsına karşı Osmanlı'dan yardım isteyecek, şehir 1551'de Turgut Reis ve Sinan Paşa tarafından alınarak Osmanlı idaresine girecektir.","kaynak":"trablusgarp"},{"bolge":4,"t":"1530-03-24","b":"Malta ve Trablus Saint Jean şövalyelerine verildi — Rodos'tan sürülen tarikatın yeni üssü","tur":"siyasi","onem":4,"dunya":2,"kapsam":"dis","etiket":["toprak-kazanc","konu-askeri","konu-siyasi","konu-din"],"yer":"Malta","yer_id":"Malta","kisiler":"Şarlken (V. Carlos)","d":"Kanûnî Sultan Süleyman'ın 928'de (1522) Rodos'tan çıkardığı Saint Jean (Hospitalier) şövalyeleri sekiz yıl yurtsuz kaldıktan sonra, İspanya-Almanya Kralı V. Carlos tarafından Malta'ya yerleştirildi; aynı bağışla Trablusgarp'ın savunması da tarikata verildi. Malta, sahip olduğu ideal limanlarıyla denizlerde etkili olan şövalyeler için elverişli bir üs hâline geldi: önce Birgu'ya yerleştiler, Saint Angelo Kalesi'ni tahkim ettiler ve Senglea ucunda Saint Michel Kalesi'ni yaptılar. Bu yerleşme, Akdeniz'in ortasında Osmanlı deniz yollarını kesen kalıcı bir düşman üssü doğurdu; Turgut Reis'in 947'de (1540) Gozo'ya akınıyla başlayan çatışmalar 1565 Malta kuşatmasına kadar sürecekti.","kaynak":"malta"},{"bolge":1,"t":"1887-01-07","b":"Çelenko Savaşı — Harar Emirliği'nin sonu ve Habeş işgali","tur":"savas","onem":2,"dunya":2,"kapsam":"dis","etiket":["toprak-kayip","savas","konu-askeri"],"yer":"Harar","yer_id":"Harar","kisiler":"Emîr Abdullah","d":"Dâvûd Aussa imamı olunca Oromolar'ın idaresindeki toprakların ortasında kalan Harar yeniden bağımsız bir emirlik hâline gelmiş ve bu hâlini 1887'deki Habeş işgaline kadar sürdürmüştü. Cihad ilân eden Emîr Abdullah 5000 kişiyle 7 Ocak 1887 günü Habeşler'i Şeleneko'da (Çelenko) karşıladı; yenileceğini anlayınca güney Harar'daki Ogaden bölgesine kaçtı. Savaş, ateşli silâhlarla donanmış Habeş ordusuyla emirliğin kuvvetleri arasındaki dengesizliği gösterdi ve Kızıldeniz ardındaki son bağımsız müslüman emirliklerinden birini ortadan kaldırdı. Harar, Cîcîga ve Dagahbûr böylece Habeşistan'a katıldı.","kaynak":"harar"},{"bolge":1,"t":"1768-05-15","b":"Korsika Ceneviz'den Fransa'ya satıldı — Versailles Antlaşması","tur":"antlasma","onem":2,"dunya":2,"kapsam":"dis","etiket":["toprak-kayip","konu-askeri","konu-diplomasi"],"yer":"Ayacyo (Ajaccio)","yer_id":"Ayacyo (Ajaccio)","kisiler":"","d":"Ceneviz Cumhuriyeti, yüzyıllardır elinde tuttuğu ama isyanlar yüzünden fiilen denetleyemediği Korsika'yı Fransa'ya devretti. TDV'nin Korsika maddesi olayı tek cümleyle veriyor: Ceneviz pek fazla sahiplenemediği bu adayı 1768'de Fransa'ya sattı. Devir, Cenova'nın Akdeniz'deki son büyük toprak varlığından çekilişini işaretler; ada 1796'da bir süre İngiliz eline geçecek, sonra yeniden Fransa'ya iade edilecektir. Adanın Fransız toprağı olması, bir yıl sonra Ajaccio'da doğacak Napolyon Bonapart'ı Fransız tebaası yapmıştır. Bu yıl (1768) Korsika, Bastia dahil, Ceneviz'den Fransa'ya satıldı (TDV Korsika; gün teyitsiz).","kaynak":"korsika | Yer teyidi (DUNYA-1102 D(b) hücre 5): TDV İslâm Ansiklopedisi, islamansiklopedisi.org.tr/korsika (1768)"},{"bolge":2,"t":"1870-09-20","b":"İtalyan birlikleri Roma'ya girdi — Papalık Devleti'nin sonu ve İtalyan birliğinin tamamlanması","tur":"savas","onem":3,"dunya":3,"kapsam":"dis","etiket":["toprak-kayip","devlet-sonu","konu-askeri","konu-siyasi"],"yer":"Roma","yer_id":"Roma","kisiler":"","d":"Fransa-Prusya Savaşı'nda III. Napolyon'un devrilmesi, Roma'yı koruyan Fransız garnizonunu geri çekince İtalyan birlikleri şehre girdi ve papa Vatikan'a çekildi. Böylece bin yılı aşkın süredir varlığını sürdüren Papalık Devleti sona erdi ve Roma'yı da birliğe katan İtalya Krallığı siyasî bir güç olarak Avrupa ve dünya sahnesine çıktı. Bu, atlasın son yarım yüzyılı için doğrudan sonuç doğuran bir olaydır: birleşmiş İtalya, 1911'de Trablusgarp'ı ve Oniki Ada'yı Osmanlı'dan alacak devlettir.","kaynak":"italya"},{"bolge":1,"t":"1720-09-02","b":"Sardinya İspanya'dan Savoy hânedanına geçti — Sardinya Krallığı doğdu","tur":"antlasma","onem":1,"dunya":2,"kapsam":"dis","etiket":["toprak-kayip","konu-askeri","konu-diplomasi","konu-kisiler","konu-hanedan"],"yer":"Kalyari (Cagliari)","yer_id":"Kalyari (Cagliari)","kisiler":"","d":"İspanya Veraset Savaşı'nı kapatan düzenlemelerin son halkasında Sardinya adası İspanya'dan alınarak Savoy hânedanına verildi; Savoy dükü karşılığında Sicilya'yı bıraktı ve Sardinya Kralı unvanını aldı. Cagliari ve Sassari böylece iki yüzyıllık İspanyol idaresinden çıktı. Doğan Sardinya Krallığı, bir buçuk asır sonra İtalyan birliğini kuracak devletin çekirdeğidir — yani 1870'te Roma'ya giren İtalya Krallığı'nın kökü buraya iner.","kaynak":"bulunamadı"},{"t":"1489-03-04","b":"Cem Sultan Roma'ya getirildi — rehin diplomasisi ve yıllık 40.000 duka","tur":"siyasi","onem":3,"dunya":3,"kapsam":"ic","etiket":["siyaset","diplomasi","konu-siyasi","konu-diplomasi"],"yer":"Roma","yer_id":"Roma","kisiler":"Cem Sultan, II. Bayezid, Papa VIII. Innocent, Pierre d'Aubusson","d":"Papa VIII. Innocent, Rodos şövalyelerinin reisi Pierre d'Aubusson ile anlaşarak Cem Sultan'ı Roma'ya getirtti (4 Mart 1489). Cem 29 Temmuz 1482'de Rodos'a sığınmış, oradan Savoie topraklarına, sonunda papalık gözetimine geçmişti. II. Bayezid, kardeşini gözaltında tutmaları karşılığında şövalyelere yıllık 40.000 duka ödemeyi ve onlara Osmanlı topraklarında serbest ticaret hakkı tanımayı kabul etmişti. Bu ödeme bir haraç değil, tahtın meşrû rakibini Avrupa'da hareketsiz tutmanın bedeliydi: Cem serbest kalsaydı Anadolu'da ordu toplayabilir, üstelik bir Haçlı seferinin meşrûiyet kaynağı olabilirdi. Böylece bir hânedan meselesi, otuz yıl boyunca Osmanlı dış siyasetinin ana kısıtı hâline geldi — Bayezid'in Batı'da ihtiyatlı davranmasının sebebi budur. Cem'in 1495'teki ölümüyle bu kısıt kalktı.","kaynak":"cem-sultan"},{"bolge":2,"t":"1701-01-18","b":"Prusya Krallığı ilan edildi — I. Friedrich Königsberg'de taç giydi","tur":"kurulus","onem":3,"dunya":4,"kapsam":"dis","etiket":["siyaset","kurulus","konu-siyasi"],"yer":"Königsberg","yer_id":"Königsberg","kisiler":"I. Friedrich, İmparator I. Leopold","d":"Brandenburg Elektörü III. Friedrich, İmparator I. Leopold'un onayıyla Königsberg'de taç giyerek «Prusya'da Kral» unvanını aldı (18 Ocak 1701). Unvan Doğu Prusya'dan alınmıştı, çünkü orası Kutsal Roma İmparatorluğu'nun dışındaydı ve imparatora bağlı bir elektör ancak imparatorluk sınırları dışında kral olabilirdi. Hohenzollern hânedanının dağınık toprakları bu tarihten sonra tek bir devlet adıyla anılmaya başlandı.","kaynak":"prusya"},{"bolge":4,"t":"1807-07-09","b":"Tilsit Antlaşması — Prusya topraklarının yarısını kaybetti, Varşova Dukalığı kuruldu","yer_kon":[55.0864,21.8892],"tur":"antlasma","onem":3,"dunya":4,"kapsam":"dis","etiket":["siyaset","diplomasi","antlasma","konu-siyasi","konu-diplomasi"],"yer":"Tilsit","kisiler":"III. Friedrich Wilhelm, Napolyon Bonapart, I. Aleksandr","d":"Jena-Auerstedt bozgunundan sonra Prusya, Napolyon ile Tilsit'te ağır bir barışı kabul etmek zorunda kaldı (9 Temmuz 1807). Elbe'nin batısındaki bütün toprakları ile 1793 ve 1795 paylaşımlarında aldığı Polonya topraklarını bıraktı; bu ikincilerden Varşova Dukalığı kuruldu ve Białystok çevresi Rusya'ya verildi. Prusya nüfusunun ve toprağının yaklaşık yarısını yitirdi, ordusu 42.000 ile sınırlandı. Atlasta Poznan ve Toruń bu günden itibaren Varşova Dukalığı'na, Białystok ise Rusya'ya geçer. Bu antlaşmayla Łódź ve Częstochowa (1772 sonrası Prusya'ya geçen Polonya eyaletleri) Varşova Dukalığı'na geçti; Gdańsk (Danzig) bağımsız serbest şehir oldu.","kaynak":"prusya · Yer teyidi (DUNYA-1102 D(b), 3 Kasım 2026): Fransa–Rusya Tilsit Antlaşması 7 Temmuz 1807, md. 5-6 — Digithèque MJP https://mjp.univ-perp.fr/traites/1807tilsit.htm"},{"bolge":2,"t":"1648-10-24","b":"Vestfalya Barışı — Otuzyıl savaşları sona erdi, Kutsal Roma'nın birliği çözüldü","yer_id":"Münster","kapsam_genis":true,"tur":"antlasma","onem":2,"dunya":5,"kapsam":"dis","etiket":["siyaset","diplomasi","antlasma","konu-siyasi","konu-diplomasi"],"yer":"Münster ve Osnabrück","kisiler":"III. Ferdinand, Kraliçe Christina, XIV. Louis","d":"Otuzyıl savaşlarını (1618-1648) bitiren antlaşmalar Münster ve Osnabrück'te aynı gün imzalandı (24 Ekim 1648). Kutsal Roma İmparatorluğu'nun üç yüz kadar prensliği kendi dış siyasetini yürütme hakkı kazandı; imparatorluk bir devlet olmaktan çıkıp bir çatıya dönüştü. İsveç Batı Pomeranya'yı ve Stettin'i aldı, Brandenburg Doğu Pomeranya ile Magdeburg başpiskoposluğunun beklentisini kazandı — Hohenzollern'in 1701'de krallığa yürüyecek toprak birikimi burada başlar. Hollanda ve İsviçre'nin bağımsızlığı resmen tanındı. Osmanlı açısından önemi dolaylı ama büyüktür: Habsburglar batı cephesinden çekilince Orta Avrupa'da yeniden doğuya dönebilecek bir güç doğdu.","kaynak":"almanya"}];

