/* ==== data/olaylar_ek21.js ==== */
// data/olaylar_ek21.js — paketle.py İNCELTTİ: ic_not* alanları yayına gitmez (kaynak dosya değişmedi)
window.OLAYLAR_EK21 = [{"tur":"savas","t":"1811-04-01","b":"Niğbolu'nun geri alınışı — altı aylık Rus işgali sona erdi","k":"savas","onem":2,"dunya":0,"kapsam":"ic","etiket":["savas","toprak-kazanc","konu-askeri"],"yer":"Niğbolu","yer_id":"Niğbolu","kisiler":"Mihail Kutuzov","d":"1806-1812 Osmanlı-Rus savaşında Tuna'nın güney yakasına geçen Rus kuvvetleri Niğbolu'yu 1810 Ekiminde General Kutuzov kumandasında ele geçirmişti. Altı ay sonra, Tuna hattını tutamayacaklarını görünce şehri boşalttılar; ayrılmadan önce kalenin önemli kısmını havaya uçurdular. TDV'nin kaydı şöyledir: \\\"1810 yılı Ekim ayında (1808-1812 Türk-Rus savaşı dönemi) Niğbolu, meşhur Rus Generali Michail Kutuzov'un kuvvetleri tarafından ele geçirildi. Ruslar, şehri terketmeden önce 1811 Nisanında kalenin önemli kısmını havaya uçurup şehre büyük zarar verdiler.\\\" Rus kuvvetlerinin çekilmesinin ardından Osmanlılar kaleyi yeniden yaptırdı; 1813-1814 tarihli kitâbe bu onarımın kaydıdır.","gun":"Nisan 1811","kaynak":"nigbolu","duygu":["⚔️"]},{"tur":"savas","t":"1811-05-01","b":"Silistre'nin tahliyesi — Tuna'nın orta kalesi surları yıkılarak bırakıldı","k":"savas","onem":2,"dunya":0,"kapsam":"ic","etiket":["savas","toprak-kazanc","konu-askeri"],"yer":"Silistre","yer_id":"Silistre","kisiler":"Mihail Kutuzov","d":"Tuna'nın en güçlü Osmanlı kalelerinden Silistre 1810'da Rus topçusunun bombardımanına uğramış, bir silâh deposunun patlamasıyla kale ve varoş ağır hasar görmüştü. Ruslar şehri ele geçirdikten sonra burayı tutmak yerine tahkimatını yok etmeyi seçtiler: General Kutuzov surların yıkılmasını emretti ve 1811 Mayısında çara Silistre surlarının havaya uçurulduğunu bildirdi. TDV'nin kaydı: \\\"1810'da şehir Ruslar tarafından bombalandı… Ruslar'ın şehri ele geçirmesinden sonra ve geri çekilmelerinden önce General Kutuzov Silistre'nin yıkılmasını emretti. 1811 Mayısında çara Silistre surlarının havaya uçurulduğunu bildirdi.\\\" Aynı kale 1827-1828 savaşında Ruslar tarafından yeniden alınacak ve o kuşatmayı Helmuth von Moltke ayrıntılı biçimde anlatacaktır.","gun":"Mayıs 1811","kaynak":"silistre","duygu":["⚔️"]},{"onem":4,"dunya":1,"bolge_onem":4,"puan_s":"v2","kapsam":"dis","bolge":3,"t":"1509-01-01","k":"siyaset","etiket":["siyaset","savas","konu-askeri","konu-siyasi"],"b":"Şah İsmâil'in Derbend'i alışı — Safevî hâkimiyeti Kafkas kapısına ulaştı","gun":"1509","yer":"Derbend (Demirkapı) — Dağıstan, Hazar kıyısı","yer_id":"Derbend","kisiler":"Şah İsmail","d":"Şirvanşah Ferruh Yesâr'ın 1500'de yenilip öldürülmesiyle Bakü ve Şemâhî Safevî eline geçmiş, Derbend ise bir süre daha ayrı kalmıştı. Şah İsmâil 1509'da şehri zaptedip Rumlu oymaklarından birini buraya yerleştirdi; böylece Safevî hâkimiyeti Kafkasya'nın kuzey kapısına, Hazar ile dağlar arasındaki bu dar geçide ulaştı. 1538'de Şirvan'ın doğrudan Safevî idaresine girmesiyle bağ kalıcılaştı. Derbend 1578 seferinde Osmanlı eline geçecek ve 1607'ye kadar yedi sancaklı bir beylerbeyiliğin merkezi olacaktır. TDV'nin kaydı şöyledir: \\\"Safevî Devleti'nin kurulup gelişmesi, Derbend'de yeni bir dönemin başlangıcını teşkil etti. Şah İsmâil 1509'da şehri zaptedip Rumlu oymaklarından birini buraya yerleştirdi. 1538'de Şirvan doğrudan Safevî hâkimiyetine girince...\\\"","kaynak":"derbend--dagistan","duygu":["🏛"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","tur":"fetih","kapsam":"ic","t":"1537-01-01","k":"fetih","etiket":["fetih","siyaset","konu-askeri","konu-siyasi"],"b":"Kars'ın Osmanlı topraklarına kesin katılışı — doğu serhaddinin çivisi","gun":"1537","yer":"Kars","yer_id":"Kars","kisiler":"Dulkadırlı Mehmed Han, Kanûnî Sultan Süleyman","d":"Akkoyunlu Devleti'nin Safevîler tarafından yıkılmasından sonra Kars bir süre Avşar Türkmenlerinden Sevündük Han Kurçibaşı'nın elinde kalmıştı. Kanûnî'nin Irakeyn Seferi sırasında (940/1534) Pasin, Şüregel ve Oltu kaleleri alınırken Kars Kalesi'nin de Osmanlılara bağlanmış olması kuvvetle muhtemeldir; ancak şehrin kesin katılışı üç yıl sonradır. TDV'nin kaydı şöyledir: \\\"Kars, Osmanlı hizmetine girmiş olan Dulkadırlı Mehmed Han tarafından kesin olarak 944'te (1537) Osmanlı topraklarına dahil edilmiştir.\\\" Uzun mücadeleler yüzünden şehir ve kale büyük ölçüde harap olduğundan hızlı bir tamirata girişildi; 955'te (1548) kale onarılırken Safevîler şehre saldırdı ve kaleyi yeniden tahrip etti. Kars bundan sonra üç yüz kırk yıl boyunca Osmanlı'nın kuzeydoğu serhaddinin kilidi olarak kalacak, 1877-78 savaşının ardından Rusya'ya bırakılacaktır.","kaynak":"kars","duygu":["⚔️"]}];

