window.OLAYLAR_SENKRON_0930 = [{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1399-09-01","kesinlik":"yil","k":"fetih","etiket":["toprak-kazanc","konu-askeri","memluk"],"b":"Yıldırım Bayezid Berkuk'un ölümünün ardından Besni, Darende ve Divriği'yi Osmanlı topraklarına kattı","gun":"1399 — TDV malatya yıl verir; 1 Eylül yalnız Malatya maddesiyle hizalama işaretidir","yer":"Divriği, Besni (Behisni), Darende","kisiler":"Yıldırım Bayezid, Memlük Sultanı Berkuk, Ferec","d":"Memlük Sultanı Berkuk'un ölümünden (Haziran 1399) sonra Memlük Devleti'nin idarî işleri bozulunca Yıldırım Bayezid Fırat havzasına indi ve Malatya ile birlikte Besni (Behisni), Darende ve Divriği'yi Osmanlı topraklarına kattı. Sivas bundan önce, Kadı Burhâneddin'in 1398 yazındaki ölümünden sonra Osmanlı'ya bırakılmıştı. Divriği 1391'den beri Memlük hâkimiyetindeydi ve Halep eyaletine bağlı bir ileri karakol durumundaydı. Osmanlı idaresi burada uzun sürmedi: yaklaşan Timur tehlikesi yüzünden Divriği 1401'de yeniden Memlükler'e verildi, şehrin kesin olarak Osmanlı idaresine girişi 1516 Mercidâbık'tan sonra oldu.","kaynak":"divrigi","duygu":["🙂"],"yer_id":"Divriği"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1401-01-01","k":"kayip","etiket":["toprak-kayip","diplomasi","konu-siyasi","memluk"],"b":"Divriği, Timur tehlikesi yüzünden yeniden Memlükler'e verildi","gun":"1401 (TDV yıl verir, ay ve gün vermez — 01-01 yalnız yıl işaretidir)","yer":"Divriği","yer_id":"Divriği","kisiler":"Yıldırım Bayezid, Memlük Sultanı Ferec, Timur","d":"Yıldırım Bayezid'in 1398'de Memlükler'den aldığı Divriği, Timur'un Anadolu'ya yaklaşması üzerine 1401'de yeniden Memlükler'e bırakıldı. Bu yüzden Timur'un Sivas'ı yıkmasından (1400) sonra Divriği haritada Memlük renginde görünür; aynı aylarda Bayezid doğuda Erzincan ve Kemah'ı alıyordu, yani Memlük toprağı Osmanlı'nın batıdaki (Sivas) ve kuzeydoğudaki (Kemah) toprakları arasında kaldı. Divriği ancak 1516 Mercidâbık'tan sonra kesin olarak Osmanlı'ya geçti.","kaynak":"divrigi","duygu":["😔"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1400-08-01","k":"kayip","etiket":["toprak-kayip","savas","konu-askeri","memluk"],"b":"Besni, Timur'un Sivas ve Malatya seferi sırasında Memlükler'e geçti","gun":"1400 (TDV yıl verir) — gün komşudan: Sivas (olaylar_ek5 1400-08-01 'Ağustos 1400', kaynak TDV sivas)","yer":"Besni (Behisni)","yer_id":"Behisni (Besni)","kisiler":"Yıldırım Bayezid","d":"Yıldırım Bayezid'in 1398'de Sivas, Darende ve Malatya ile birlikte aldığı Besni, 1400'de Timur Sivas ve Malatya'yı alırken Memlükler'in eline geçti. Timur 27 Eylül 1400'de şiddetli bir kuşatmadan sonra Besni'yi de zaptetti; o bölgeden çekilince Besni yeniden Memlük hâkimiyetine girdi ve 1516 Ağustosunda Yavuz Sultan Selim alana dek (Dulkadırlı bir ara dönem dışında) Memlük'te kaldı.","kaynak":"besni","duygu":["😔"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","tur":"savas","kapsam":"dis","bolge":3,"t":"1414-01-01","k":"savas","etiket":["savas","konu-askeri","memluk","dulkadir"],"b":"Memlük Sultanı Şeyh, Antep ile Darende'yi Dulkadırlılar'dan geri aldı","gun":"1414 (TDV yıl verir, ay ve gün vermez — 01-01 yalnız yıl işaretidir)","yer":"Darende, Antep","yer_id":"Darende","kisiler":"Memlük Sultanı Şeyh el-Mahmûdî, Dulkadıroğlu Nâsırüddin Mehmed Bey","d":"Dulkadırlılar'ın Osmanlılar'la dostluğundan endişelenen Memlük Sultanı Şeyh 1414'te sefere çıktı; daha önce kendi rızasıyla Dulkadırlılar'a verdiği Antep ile Darende'yi geri aldı.","kaynak":"dulkadirogullari","duygu":["⚔️"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","tur":"savas","kapsam":"dis","bolge":3,"t":"1418-01-01","k":"savas","etiket":["savas","konu-askeri","memluk","dulkadir"],"b":"Dulkadıroğlu Mehmed Bey Darende'yi geri aldı, Besni'yi de topraklarına kattı","gun":"1418 (TDV yıl verir, ay ve gün vermez — 01-01 yalnız yıl işaretidir)","yer":"Darende, Besni","yer_id":"Darende","kisiler":"Dulkadıroğlu Nâsırüddin Mehmed Bey","d":"Memlükler'in 1414'te aldığı Darende'yi Dulkadıroğlu Mehmed Bey 1418'de geri aldı ve Besni'yi de topraklarına kattı.","kaynak":"dulkadirogullari","duygu":["⚔️"]},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"dis","bolge":3,"t":"1436-01-01","k":"kayip","etiket":["toprak-kayip","konu-askeri","memluk","dulkadir"],"b":"Memlükler Antep'te Dulkadırlılar'ı yendi; Besni Memlük idaresine döndü (yaklaşık)","gun":"1436 (TDV yıl verir, ay ve gün vermez — 01-01 yalnız yıl işaretidir)","yer":"Antep, Besni","yer_id":"Behisni (Besni)","kisiler":"Dulkadıroğlu Nâsırüddin Mehmed Bey","d":"Memlük ordusu 1436'da Antep'te Dulkadırlılar'ı yendi, Mehmed Bey Akdağ'a çekildi. Besni'nin Memlük'e dönüş yılı kaynakta yazılı değil; Besni 1418'de Dulkadır'a katılmış, Şehsuvar Bey'in 1465'te onu Memlükler'den almasından önce Memlük'e dönmüştü. Atlas, Besni'yi komşu merkez Antep'teki bu yenilgiyle birlikte (beyanlı yaklaşıklık) Memlük'e geri verir.","kaynak":"dulkadirogullari","duygu":["😔"]},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"dis","bolge":3,"t":"1467-01-01","k":"fetih","etiket":["toprak-kazanc","konu-askeri","memluk","dulkadir"],"b":"Dulkadıroğlu Şehsuvar Bey Besni'yi Memlükler'den aldı (yaklaşık)","gun":"1467 (yıl yaklaşık; TDV Şehsuvar'ın alış yılını vermez)","yer":"Besni, Gerger, Birecik, Rumkale","yer_id":"Behisni (Besni)","kisiler":"Şehsuvar Bey","d":"Fatih Sultan Mehmed tarafından Dulkadır beyi atanan Şehsuvar Bey (1465-1472) Memlükler'in elindeki Besni, Gerger, Birecik ve Rumkale'yi zaptetti; Memlükler 1467 sonbaharında Turnadağı'nda, 1468 ilkbaharında Antep yakınlarında yenildi.","kaynak":"dulkadirogullari","duygu":["⚔️"]},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"dis","bolge":3,"t":"1471-01-01","k":"kayip","etiket":["toprak-kayip","konu-askeri","memluk","dulkadir"],"b":"Emîr Yeşbek Şehsuvar Bey'i yendi; Besni Memlük idaresine döndü (yaklaşık)","gun":"1471 (TDV yıl/ilkbahar verir, gün vermez — 01-01 yalnız yıl işaretidir)","yer":"Besni, Kadirli, Kozan","yer_id":"Behisni (Besni)","kisiler":"Şehsuvar Bey, Emîr Yeşbek","d":"1471 ilkbaharında Emîr Yeşbek Savron deresinde Şehsuvar Bey'i yendi; Memlükler Kadirli ve Kozan'ı geri aldı. Şehsuvar 1472'de Kahire'de idam edildi, Memlükler Şahbudak'ı yeniden beyliğe getirdi. Besni de bu dönüşle Memlük idaresine girdi (TDV besni: 'XV. yüzyılın sonlarına doğru yeniden Memlükler’in eline geçti').","kaynak":"dulkadirogullari","duygu":["😔"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","kapsam":"ic","t":"1551-07-26","k":"kayip","etiket":["toprak-kayip","siyaset","konu-siyasi","erdel","habsburg"],"b":"Erdel Habsburg idaresine geçti: Kolozsvár meclisi İzabella'nın feragatini tanıdı","gun":"26 Temmuz 1551","yer":"Kolozsvár (Kaloşvar), Erdel Belgradı (Gyulafehérvár), Szászsebes, Brassó (Braşov), Segesvár (Sighişoara), Szatmár (Satu Mare), Gyula (Göle), Varad (Oradea)","kisiler":"Kraliçe İzabella, János Zsigmond, Martinuzzi (Fráter György), General Castaldo, Ferdinand","d":"Martinuzzi'nin Ferdinand'la anlaşması üzerine Kraliçe İzabella, küçük kral János Zsigmond adına 19 Haziran 1551'de Szászsebes kalesinde kendisine dayatılan feragatnameyi imzaladı. 26 Temmuz'da Kolozsvár'da toplanan Erdel meclisi bu feragati ve Kral Ferdinand'ın hâkimiyetini tanıdı; General Castaldo'nun Habsburg ordusu Erdel Belgradı'na (Gyulafehérvár) girdi. Böylece Osmanlı'ya bağlı Erdel, beş yıl sürecek bir Habsburg idaresine geçti.","kaynak":"History of Transylvania I (ed. B. Köpeczi), 'Downfall and Renewal' — mek.oszk.hu/03400/03407/html/102.html · TDV erdel","yer_id":"Erdel (Kaloşvar)","duygu":["😔"]},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","kapsam":"ic","t":"1556-03-12","k":"fetih","etiket":["toprak-kazanc","konu-siyasi","erdel","habsburg"],"b":"Habsburg idaresi Erdel'de sona erdi: Erdel yeniden Osmanlı'ya bağlı voyvodalık oldu","gun":"12 Mart 1556","yer":"Erdel (Kaloşvar), Erdel Belgradı (Gyulafehérvár), Brassó (Braşov), Segesvár (Sighişoara), Szatmár (Satu Mare)","kisiler":"János Zsigmond, İzabella, Martinuzzi (Fráter György), Ferdinand","d":"János Zsigmond'un küçük yaşta olması sebebiyle ona vasî tayin edilen Hırvat asıllı papaz Martinuzzi (Fráter György) eliyle Habsburglar 1551'de Erdel'e hâkim olmaya çalıştı; Erdel Belgradı (Gyulafehérvár), Kaloşvar, Brassó ve Segesvár beş yıl Habsburg idaresinde kaldı. Osmanlılar bu durumu önledi ve Erdel yeniden kendisine bağlı haraçgüzâr voyvodalık hâline geldi. Erdel bundan sonra XVI ve XVII. yüzyıllarda yaklaşık 150 yıl boyunca iç işlerinde geniş muhtariyete, dış işlerinde İstanbul'a bağlılığa dayanan statüsünü korudu.","kaynak":"erdel","duygu":["🙂"],"yer_id":"Erdel (Kaloşvar)"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1550-09-15","kesinlik":"ay","k":"siyaset","etiket":["siyaset","konu-askeri","habsburg"],"b":"Ferdinand'ın kuvvetleri Solnok'u tuttu ve tahkim etti","gun":"Eylül ortası 1550","yer":"Solnok (Szolnok)","yer_id":"Solnok (Szolnok)","kisiler":"I. Ferdinand","d":"Osmanlılar Tisza üzerindeki Solnok'ta kale kurmaya hazırlanırken I. Ferdinand'ın kuvvetleri öne geçti: Eylül 1550 ortasında Solnok'u tuttular ve kale Ekim ortasında savunulabilir hâle getirildi. Böylece İzabella'nın ülkesine ait Solnok, Erdel'in Ferdinand'a geçişinden bir yıl önce Habsburg eline geçti; Osmanlılar kaleyi 1552'de aldı.","kaynak":"Bánlaky, A magyar nemzet hadtörténelme (MEK 09477) 0013/988: 'szeptember közepe táján … meg is szállották Szolnokot … október 16.-án védképes állapotban volt'"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1565-02-01","kesinlik":"ay","k":"siyaset","etiket":["siyaset","konu-askeri","erdel","habsburg"],"b":"Schwendi Szatmár'ı aldı — Erdel'in kuzey ucu Habsburg'a geçti","gun":"Şubat 1565","yer":"Szatmár (Satu Mare), Tokaj","yer_id":"Szatmár (Satu Mare)","kisiler":"Lazarus von Schwendi, János Zsigmond, Báthory István","d":"1561'de Balassa Menyhért'in taraf değiştirmesiyle Habsburg'a geçen Szatmár'ı Báthory István 1564 sonbaharında baskınla geri almış, Erdel'e katmıştı. Habsburg komutanı Lazarus von Schwendi Şubat 1565'te karşı harekâta geçti: Tokaj 9 Şubat'ta, Szerencs dört gün sonra düştü ve Szatmár hemen hemen direnişsiz imparatorluk kuvvetlerinin eline geçti.","kaynak":"MTA History of Transylvania (mek.oszk.hu/03400/03407/html/105.html): 'in 1564, he led a surprise attack to seize Szatmár and Németi' · Bánlaky (MEK 09477) 0013/1049: 'Szatmár úgyszólván ellenállás nélkül került a … császáriak kezébe'"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1605-01-21","k":"siyaset","etiket":["siyaset","ayaklanma","konu-askeri","erdel"],"b":"Bocskai'nin kuvvetleri Szatmár'ı aldı","gun":"21 Ocak 1605","yer":"Szatmár (Satu Mare)","yer_id":"Szatmár (Satu Mare)","kisiler":"Bocskai István, Gyulaffy","d":"Bocskai ayaklanması kuzeydoğu Macaristan'a yayılırken Gyulaffy kuşattığı Szatmár'ı 21 Ocak 1605'te ele geçirdi. 23 Haziran 1606 Viyana barışı Szatmár ilini ömür boyu Bocskai'ye bıraktı; erkek varis olmadığından Bocskai'nin 29 Aralık 1606'daki ölümüyle il krallığa döndü.","kaynak":"MTA History of Transylvania (mek.oszk.hu/03400/03407/html/119.html): 'laid siege … to … Szatmár, and invested it on 21 January' · 120.html: 'He died at Kassa on 29 December 1606' · TDV zitvatorok-antlasmasi: 'Macar heyeti barış şartlarını kabul etti (23 Haziran 1606)'"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1619-11-01","kesinlik":"ay","k":"siyaset","etiket":["siyaset","konu-askeri","erdel"],"b":"Bethlen Gábor Szatmár ilini denetimine aldı","gun":"Kasım 1619","yer":"Szatmár (Satu Mare)","yer_id":"Szatmár (Satu Mare)","kisiler":"Bethlen Gábor","d":"Bethlen Gábor'un 1619 sonbaharındaki Macaristan seferiyle Szatmár ili Erdel prensinin denetimine girdi; Kasım 1619'da ile mektupla hitap ediyordu. 23 Ocak 1620 ön antlaşması ve Nikolsburg barışı Szatmár'ı da içine alan yedi ili Bethlen'e ömür boyu bıraktı. Bethlen'in ölümünden (15 Kasım 1629) sonra illerin krallığa iadesi 30 Mart 1630'da tamamlandı.","kaynak":"MTA History of Transylvania (mek.oszk.hu/03400/03407/html/183.html): 'Seven counties — Szatmár, … — would remain under his rule' · 188.html: 'by 30 March 1630 they could report success'"},{"onem":3,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1664-05-03","k":"kayip","etiket":["toprak-kayip","konu-askeri"],"b":"Nitra'nın kaybı — De Souches kaleyi geri aldı","gun":"3 Mayıs 1664","yer":"Nitra (Nyitra)","yer_id":"Nitra (Nyitra)","kisiler":"Jean-Louis Raduit de Souches","d":"1663'te Uyvar'ın fethinden sonra kısa direnişle teslim olan Nitra'yı imparatorluk komutanı De Souches 15 Nisan 1664'te kuşattı; kale 3 Mayıs 1664'te teslim oldu. Vasvar Antlaşması ele geçen yerleri bulunduğu hâlde bıraktığından Uyvar Osmanlı'da kalırken Nitra Habsburg elinde kaldı.","kaynak":"Bánlaky (MEK 09477) 0016/1325: 'április 15-én Nyitra alá érkezett' · 0016/1322: 'Nyitra május 3-án kénytelen volt magát megadni' · 0016/1341 (Vasvár: Érsekújvár Osmanlı'da)"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1664-06-14","k":"kayip","etiket":["toprak-kayip","konu-askeri"],"b":"Léva'nın kaybı","gun":"14 Haziran 1664","yer":"Léva (Levice)","yer_id":"Léva (Levice)","kisiler":"Jean-Louis Raduit de Souches","d":"De Souches Nitra'dan sonra 9 Haziran 1664'te Léva'yı kuşattı; 13 Haziran'da kapitülasyon imzalandı ve kale 14 Haziran'da imparatorluk kuvvetlerinin elindeydi. 19 Temmuz 1664'teki Léva (Garamszentbenedek) muharebesi sahipliği değiştirmedi; Habsburg'un Léva ve Nitra'yı elde tutmasıyla sonuçlandı.","kaynak":"Bánlaky (MEK 09477) 0016/1331: 'Léva vára másnap, azaz június 14-én a császáriak kezében volt' · 0016/1333: 'Léva és Nyitra várak megtartattak'"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","kapsam":"ic","t":"1606-12-29","k":"siyaset","etiket":["siyaset","konu-siyasi","konu-kisiler","erdel","habsburg"],"b":"Bocskai István'ın ölümü — Szatmár ili krallığa döndü","gun":"29 Aralık 1606","yer":"Kassa (Košice), Szatmár (Satu Mare)","yer_id":"Szatmár (Satu Mare)","kisiler":"Bocskai István","d":"Erdel prensi Bocskai István 29 Aralık 1606'da Kassa'da öldü. Viyana barışı (23 Haziran 1606) Szatmár'ı da içine alan illeri ona ömür boyu, erkek varis olmaması hâlinde krallığa dönmek üzere bırakmıştı; bu hükümle Szatmár ili Habsburg Macar krallığına geri geçti. Erdel yeni bir prens arayışına girdi.","kaynak":"MTA History of Transylvania (mek.oszk.hu/03400/03407/html/120.html): 'He died at Kassa on 29 December 1606' · 119.html: Viyana barışı, 'Partium … encompass the counties of Szatmár' · TDV zitvatorok-antlasmasi (23 Haziran 1606)"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1630-03-30","k":"siyaset","etiket":["siyaset","konu-siyasi","erdel","habsburg"],"b":"Bethlen Gábor'un yedi ilinin krallığa iadesi tamamlandı","gun":"30 Mart 1630","yer":"Szatmár (Satu Mare), Kassa (Košice)","yer_id":"Szatmár (Satu Mare)","kisiler":"Bethlen Gábor, II. Ferdinand","d":"Nikolsburg barışı Szatmár dahil yedi Yukarı Macaristan ilini Bethlen Gábor'a ömür boyu bırakmıştı. Bethlen'in 15 Kasım 1629'daki ölümünden sonra illerin krallığa iadesi 30 Kasım 1629 talimatıyla başladı ve 30 Mart 1630'da tamamlandı.","kaynak":"MTA History of Transylvania (mek.oszk.hu/03400/03407/html/183.html): 'Seven counties — Szatmár, … — would remain under his rule' · 188.html: 'by 30 March 1630 they could report success'"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1644-02-01","kesinlik":"ay","k":"siyaset","etiket":["siyaset","konu-askeri","erdel","habsburg"],"b":"I. Rákóczi György Szatmár'ı teslim aldı","gun":"Şubat-Mart 1644","yer":"Szatmár (Satu Mare)","yer_id":"Szatmár (Satu Mare)","kisiler":"I. Rákóczi György","d":"Erdel prensi I. Rákóczi György'nün 1644 seferinde Szatmár'ın Alman garnizonu Rákóczi'nin hizmetine geçti ve kale Erdel'in eline girdi. 16 Aralık 1645 Linz barışı kaleyi, Erdel tahtında bir Rákóczi bulundukça Rákóczi varislerine bıraktı.","kaynak":"Bánlaky (MEK 09477) 0015/1291: 'a szatmári német őrség szintén Rákóczyék zsoldjába szegődött' · 0015/1292: 'a diplomát Linzben írta alá 1645 december 16-án' · MTA History of Transylvania (195.html)"},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","tur":"vassal","kapsam":"ic","t":"1372-01-01","kesinlik":"yil","k":"vassal","etiket":["siyaset","diplomasi","konu-diplomasi","konu-siyasi"],"b":"Bizans İmparatorluğu Osmanlı'nın haraçgüzârı oldu","gun":"1372 kışı","yer":"İstanbul, Selanik, Gelibolu, Silivri","yer_id":"İstanbul","kisiler":"V. Ioannes Palaiologos, I. Murad","d":"Çirmen zaferinden (1371) sonra Bizans imparatoru V. Ioannes, 1372 kışında I. Murad'ın haraçgüzârı olmayı kabul etti: yıllık haraç ödeyecek ve sultanın seferlerine asker verecekti. Bizans bu tarihten 1403'e dek Osmanlı'ya bağlı bir vasal devlet olarak kaldı; Yıldırım Bayezid'in 1391 ablukası haracı artırdı. Ankara bozgunundan sonra Süleyman Çelebi ile yapılan Gelibolu antlaşması (1403) Bizans'ı haraçtan kurtardı; 1424'te II. Murad ile yapılan antlaşmayla haraç yeniden başladı.","kaynak":"murad-i"},{"onem":4,"dunya":2,"bolge_onem":4,"puan_s":"v2","kapsam":"ic","t":"1676-09-19","k":"kayip","etiket":["toprak-kayip","siyaset","konu-askeri","konu-siyasi"],"b":"Doroşenko Çehrin'i Samoyloviç'e teslim etti","gun":"19 Eylül 1676","yer":"Çehrin (Çigirin)","yer_id":"Çehrin (Çigirin)","kisiler":"Petro Doroşenko, İvan Samoyloviç, Grigoriy Romodanovski","d":"Osmanlı himayesindeki Sağ Yaka hatmanı Petro Doroşenko, başkenti Çehrin'i 19 Eylül 1676'da Sol Yaka hatmanı Samoyloviç ve Rus kuvvetlerine teslim etti. Osmanlılar Doroşenko'yu görevden alıp yerine Yuri Hmelnitski'yi getirdi; Çehrin'deki Rus garnizonunu çıkarmak için 1677'de kuşatma başarısız kaldı, kale ancak 21 Ağustos 1678'de alındı.","kaynak":"Encyclopedia of Ukraine (CIUS) «Doroshenko, Petro»: 'surrendered to Samoilovych on 19 September 1676' · TDV cehrin-seferi (1677, 1678)"},{"onem":2,"dunya":1,"bolge_onem":2,"puan_s":"v2","kapsam":"ic","t":"1557-01-01","kesinlik":"yil","k":"siyaset","etiket":["siyaset","konu-askeri","erdel","habsburg"],"b":"Várad, Huszt ve Tokaj Szapolyai tarafına geçti","gun":"1557","yer":"Varad (Oradea)","yer_id":"Varad (Oradea)","kisiler":"Varkocs Tamás, Patócsy Ferenc, İzabella, János Zsigmond","d":"İzabella ve János Zsigmond'un 1556'da Erdel'e dönüşünün ardından Szapolyai yanlıları 1556'da Nagyvárad'ı kuşattı. 1557'de Yukarı Tisza aristokratları en önemli kral kalelerini — Várad, Huszt ve Tokaj — ele geçirdi; Ferdinand'ın elinde yalnız Gyula ve Világos kaldı. Várad bundan sonra Erdel prensliğinin kalesi oldu ve 1660'ta Osmanlılar alana dek öyle kaldı.","kaynak":"MTA History of Transylvania (mek.oszk.hu/03400/03407/html/103.html): 'gained control of the most important royal fortresses, those at Várad, Huszt, and Tokaj' · 'Only Gyula and Világos managed to hold out' · Bánlaky (MEK 09477) 0013/1029 (1556 kuşatması)"},{"onem":3,"dunya":1,"bolge_onem":3,"puan_s":"v2","bolge":2,"t":"1298-01-01","kesinlik":"yil","k":"fetih","kapsam":"dis","taraflar":["memluk","kilikya-ermeni"],"etiket":["savas","konu-askeri"],"b":"Maraş Memlüklere geçti — Halep nâibi Bilbân et-Tabahî Ermenilerden geri aldı","gun":"697 (1298) — TDV yalnız yılı veriyor","yer":"Maraş","yer_id":"Maraş","kisiler":"Bilbân et-Tabahî","d":"1258'den beri Kilikya Ermeni Krallığı'nın elinde bulunan Maraş, 1293'te Sultan Halil'in Ermenilerle yaptığı antlaşmayla kısa bir süre Memlüklere geçmiş, onların çekilmesinden sonra yeniden Ermenilerin eline düşmüştü. 697'de (1298) Memlüklerin Halep nâibi Bilbân et-Tabahî şehri geri aldı. Maraş bundan sonra Dulkadırlıların yükselişine kadar Memlük toprağı olarak kaldı.","kaynak":"kahramanmaras"}];

